M.prev = () => { const Q = queue(); if (!Q.length || !NOW) return; const i = Q.indexOf(NOW.id); const nx = Q[(i - 1 + Q.length) % Q.length]; if (G.top(APP) && G.top(APP).id === 'player') G.back(APP); M.play(nx); };
